namespace RonSijm.FluidHumidifier.Factories.Lex;

public class InnerBotRuntimeSettingsFactory(Action<Humidifier.Lex.BotTypes.RuntimeSettings> factoryAction = null) : SubResourceFactory<Humidifier.Lex.BotTypes.RuntimeSettings>
{

    internal InnerBotSlotResolutionImprovementSpecificationFactory SlotResolutionImprovementSpecificationFactory { get; set; }

    internal InnerBotNluImprovementSpecificationFactory NluImprovementSpecificationFactory { get; set; }

    protected override Humidifier.Lex.BotTypes.RuntimeSettings Create()
    {
        var runtimeSettingsResult = CreateRuntimeSettings();
        factoryAction?.Invoke(runtimeSettingsResult);

        return runtimeSettingsResult;
    }

    private Humidifier.Lex.BotTypes.RuntimeSettings CreateRuntimeSettings()
    {
        var runtimeSettingsResult = new Humidifier.Lex.BotTypes.RuntimeSettings();

        return runtimeSettingsResult;
    }
    public override void CreateChildren(Humidifier.Lex.BotTypes.RuntimeSettings result)
    {
        base.CreateChildren(result);

        result.SlotResolutionImprovementSpecification ??= SlotResolutionImprovementSpecificationFactory?.Build();
        result.NluImprovementSpecification ??= NluImprovementSpecificationFactory?.Build();
    }

} // End Of Class

